<template>
  <Transition name="slide-fade"
    ><LoadingScreen v-show="loadingScreen" ref="loadingScreen"
  /></Transition>
  <Transition name="slide-side-right">
    <AuthPanel v-show="authPanel" ref="panel" />
  </Transition>
</template>

<script>
import LoadingScreen from "./LoadingScreen.vue";
import AuthPanel from "./AuthPanel.vue";

export default {
  name: "Auth",
  components: { LoadingScreen, AuthPanel },
  data() {
    return {
      loadingScreen: false,
      authPanel: false,
    };
  },
  methods: {
    startLoading(sec = 5) {
      this.loadingScreen = true;
      setTimeout(() => {
        this.loadingScreen = false;
        setTimeout(() => {
          this.authPanel = true;
          this.$refs.panel.play();
        }, 1000);
      }, sec * 1000);
    },
  },
};
</script>

<style scoped lang="scss">
.slide-fade-leave-active {
  transition: all 0.8s cubic-bezier(1, 0.5, 0.8, 1);
}

.slide-fade-enter-from,
.slide-fade-leave-to {
  transform: translatey(-20px);
  opacity: 0;
}
</style>
