<template>
  <form @submit="submit">
    <div class="AuthRegister">
      <div class="AuthRegisterInput">
        <label for="registerUsernameInput">Username</label>
        <Input
          :invalid="this.v$.username.$error || usernameAlreadyExists"
          v-model="username"
          id="registerUsernameInput"
        />
        <InputErrorList
          v-if="this.v$.username.$error"
          :errors="this.v$.username.$errors"
        />
        <InputErrorList
          v-if="usernameAlreadyExists"
          :errors="
            usernameAlreadyExists
              ? [{ $message: 'Username already exists' }]
              : []
          "
        />
      </div>
      <div class="AuthRegisterInput">
        <label for="registerEmailInput">Email</label>
        <Input
          :invalid="this.v$.email.$error"
          v-model="email"
          id="registerEmailInput"
        />
        <InputErrorList
          v-if="this.v$.email.$error"
          :errors="this.v$.email.$errors"
        />
      </div>
      <div class="AuthRegisterInput">
        <div class="AuthRegisterLabel">
          <label for="registerPasswordInput">Password</label>
          <i
            @click="showPassword = !showPassword"
            :class="[
              'fa-duotone',
              { 'fa-eye': showPassword, 'fa-eye-slash': !showPassword },
            ]"
          ></i>
        </div>
        <Input
          :type="showPassword ? 'text' : 'password'"
          :invalid="this.v$.password.$error"
          v-model="password"
          id="registerPasswordInput"
        />
        <InputErrorList
          v-if="this.v$.password.$error"
          :errors="this.v$.password.$errors"
        />
      </div>
      <div class="AuthRegisterInput">
        <div class="AuthRegisterLabel">
          <label for="registerConfirmPasswordInput">Confirm Password</label>
          <i
            @click="showConfirmPassword = !showConfirmPassword"
            :class="[
              'fa-duotone',
              {
                'fa-eye': showConfirmPassword,
                'fa-eye-slash': !showConfirmPassword,
              },
            ]"
          ></i>
        </div>
        <Input
          :type="showConfirmPassword ? 'text' : 'password'"
          :invalid="this.v$.confirmPassword.$error"
          v-model="confirmPassword"
          id="registerConfirmPasswordInput"
        />
        <InputErrorList
          v-if="this.v$.confirmPassword.$error"
          :errors="this.v$.confirmPassword.$errors"
        />
      </div>
      <Button type="submit">Register</Button>
      <p class="AuthRegisterHasAccount">
        Have an account?
        <button @click="$emit('toggleLogin', 0)">
          <strong>Login</strong>
        </button>
      </p>
    </div>
  </form>
</template>

<script>
import Input from "../../components/Input.vue";
import Button from "../../components/Button.vue";
import InputErrorList from "../../components/InputErrorList.vue";
import useVuelidate from "@vuelidate/core";
import {
  required,
  email,
  sameAs,
  helpers,
  minLength,
  maxLength,
} from "@vuelidate/validators";

export default {
  name: "AuthRegister",
  components: { Input, Button, InputErrorList },
  emits: ["toggleLogin"],
  setup: () => ({ v$: useVuelidate() }),
  data() {
    return {
      username: null,
      email: null,
      password: null,
      confirmPassword: null,
      showPassword: false,
      showConfirmPassword: false,
      usernameAlreadyExists: false,
    };
  },
  watch: {
    username() {
      if (this.usernameAlreadyExists)
        return (this.usernameAlreadyExists = false);
    },
  },
  validations() {
    return {
      username: {
        minLength: helpers.withMessage(
          "Username should be at least 3 characters long",
          minLength(3)
        ),
        maxLength: maxLength(30),
        required: helpers.withMessage(
          "Username field cannot be empty",
          required
        ),
      },
      email: {
        maxLength: maxLength(320),
        email: helpers.withMessage(
          "Email field must be a valid email address",
          email
        ),
        required: helpers.withMessage("Email field cannot be empty", required),
      },
      password: {
        minLength: helpers.withMessage(
          "Password should be at least 8 characters long",
          minLength(8)
        ),
        maxLength: maxLength(320),
        required: helpers.withMessage(
          "Password field cannot be empty",
          required
        ),
      },
      confirmPassword: {
        sameAs: helpers.withMessage(
          "Confirm Password field must match Password field",
          sameAs(this.password)
        ),
        required: helpers.withMessage(
          "Confirm Password field cannot be empty",
          required
        ),
      },
    };
  },
  methods: {
    async submit(e) {
      e.preventDefault();
      const result = await this.v$.$validate();
      if (!result) return;

      global.gm.$refs.auth.$refs.panel.authLoading = true;
      // eslint-disable-next-line
      mp.trigger(
        "registerInformationToServer",
        this.email,
        this.username,
        this.password
      );
    },
  },
};
</script>

<style scoped lang="scss">
.AuthRegister {
  width: 235px;

  .AuthRegisterInput {
    display: flex;
    flex-direction: column;

    margin-bottom: 5px;

    .AuthRegisterLabel {
      display: flex;
      align-items: center;

      i {
        color: $gray;
        font-size: 15px;
        margin-left: 2px;
      }
    }
  }

  button {
    margin-top: 3px;
  }

  .AuthRegisterHasAccount {
    color: $white-text;
    margin-top: 5px;
  }
}
</style>
