<template>
  <div
    v-show="quickLoginUsername"
    @click="quickLogin"
    class="AuthLoginQuickLogin"
  >
    <div class="AuthLoginQuickLoginIcon">
      <i class="fa-duotone fa-bolt"></i>
    </div>
    <button class="AuthLoginQuickLoginText">
      Quick-login as <strong>{{ quickLoginUsername }}</strong>
    </button>
  </div>
  <form @submit="submit">
    <div class="AuthLogin">
      <div class="AuthLoginInput">
        <div class="AuthLoginLabel">
          <label for="loginUsernameInput">Username</label
          ><i @click="findUsernames" class="fa-duotone fa-circle-question"></i>
        </div>
        <Input
          :invalid="this.v$.username.$error || loginError"
          v-model="username"
          id="loginUsernameInput"
        />
        <InputErrorList
          v-if="this.v$.username.$error"
          :errors="this.v$.username.$errors"
        />
        <InputErrorList
          :errors="
            loginError
              ? [{ $message: 'Username or password is incorrect' }]
              : []
          "
        />
      </div>
      <div class="AuthLoginInput">
        <div class="AuthLoginLabel">
          <label for="loginPasswordInput">Password</label>
          <i
            @click="showPassword = !showPassword"
            :class="[
              'fa-duotone',
              { 'fa-eye': showPassword, 'fa-eye-slash': !showPassword },
            ]"
          ></i>
        </div>
        <Input
          :invalid="this.v$.password.$error || loginError"
          v-model="password"
          :type="showPassword ? 'text' : 'password'"
          id="loginPasswordInput"
        />
        <InputErrorList
          v-if="this.v$.password.$error"
          :errors="this.v$.password.$errors"
        />
        <InputErrorList
          :errors="
            loginError
              ? [{ $message: 'Username or password is incorrect' }]
              : []
          "
        />
      </div>
      <Button type="submit">Login</Button>
      <p class="AuthLoginNewRegister">
        Don't have an account?
        <button @click="$emit('toggleLogin', 1)">
          <strong>Register</strong>
        </button>
      </p>
    </div>
  </form>
</template>

<script>
import Input from "../../components/Input.vue";
import Button from "../../components/Button.vue";
import InputErrorList from "../../components/InputErrorList.vue";
import { useGlobalsStore } from "../../stores/globals";
import useVuelidate from "@vuelidate/core";
import { required, helpers } from "@vuelidate/validators";

export default {
  name: "AuthLogin",
  components: { Input, Button, InputErrorList },
  emits: ["toggleLogin"],
  data() {
    return {
      username: null,
      password: null,
      foundUsernames: this.devMode ? ["RotX", "Obama"] : [],
      quickLoginUsername: this.devMode ? "RotX" : null,
      showPassword: false,
      loginError: false,
    };
  },
  methods: {
    quickLogin() {
      // eslint-disable-next-line
      mp.trigger("autologinToServer", this.quickLoginUsername);
    },
    findUsernames() {
      if (this.foundUsernames.length < 1)
        return global.Modal.fire("No usernames found", "", "error");

      global.Modal.fire(
        "Found the following usernames",
        this.foundUsernames.join("<br>"),
        "success"
      );
    },
    async submit(e) {
      e.preventDefault();
      const result = await this.v$.$validate();
      if (!result) return;

      global.gm.$refs.auth.$refs.panel.authLoading = true;
      // eslint-disable-next-line
      mp.trigger("loginInformationToServer", this.username, this.password);
    },
  },
  setup() {
    const globals = useGlobalsStore();
    return { devMode: globals.devMode, v$: useVuelidate() };
  },
  watch: {
    username() {
      if (this.loginError) return (this.loginError = false);
    },
    password() {
      if (this.loginError) return (this.loginError = false);
    },
  },
  validations() {
    return {
      username: {
        required: helpers.withMessage(
          "Username field cannot be empty",
          required
        ),
      },
      password: {
        required: helpers.withMessage(
          "Password field cannot be empty",
          required
        ),
      },
    };
  },
};
</script>

<style scoped lang="scss">
.AuthLogin {
  width: 235px;
  .AuthLoginInput {
    display: flex;
    flex-direction: column;
    margin-bottom: 5px;
    .AuthLoginLabel {
      display: flex;
      align-items: center;

      i {
        color: $gray;
        font-size: 15px;
        margin-left: 2px;
      }
    }
  }

  button {
    margin-top: 3px;
  }

  .AuthLoginNewRegister {
    color: $white-text;
    margin-top: 5px;
  }
}

.AuthLoginQuickLogin {
  background: darken($foreground, 2%);
  border-radius: 50px;
  display: flex;
  color: $white-text;
  margin: 10px 0;
  padding: 5px;
  transition: background 0.4s;

  &:hover {
    background: darken($foreground, 3%);
  }

  .AuthLoginQuickLoginIcon {
    background: lighten($foreground, 2%);
    font-size: 20px;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
  }
  .AuthLoginQuickLoginText {
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 0 5px;

    strong {
      margin-left: 4px;
    }
  }
}
</style>
